/bin/bash -lc "python - <<'PY'
from ansible.plugins.shell.powershell import _parse_clixml
cases = {
    'unicode escape-like literal': '<S S=\"Error\">_x\\u6100\\u6200\\u6300\\u6400_</S>'.encode('utf-8'),
    'malformed XML': b'<S S=\"Error\">bad</Objs>',
    'incomplete XML': b'<S S=\"Error\">partial',
}
for name, body in cases.items():
    data = b'#< CLIXML\\r\\n<Objs Version=\"1.1.0.1\">' + body + (b'' if name == 'incomplete XML' else b'</Objs>' if name "'!= '"'malformed XML' else b'')
    try:
        print(name, repr(_parse_clixml(data)))
    except Exception as exc:
        print(name, type(exc).__name__, str(exc))
PY"

